// FINMENTOR Command Center — Settings sheet rows to a config object.
//
// Deployed as the n8n Code node "Settings to Object".
//
// Divergence from the shared version used by other workflows: the hardcoded owner chat id
// fallback has been removed. A literal id baked into code is an authorisation bypass — it
// keeps granting access even if the owner clears or changes the allowlist in Settings.
// The Settings sheet is now the only policy source, and an unset allowlist denies everyone.

const rows = $input.all().map(i => i.json);
const settings = {};
for (const r of rows) {
  const key = (r.key ?? r.Key ?? '').toString().trim();
  if (!key) continue;
  settings[key] = (r.value ?? r.Value ?? '').toString().trim();
}
function bool(v, def) {
  if (v === undefined || v === '') return def;
  return String(v).toLowerCase() === 'true' || v === '1';
}
function num(v, def) {
  const n = Number(v);
  return Number.isFinite(n) ? n : def;
}
const cfg = {
  owner_chat_id: settings.owner_chat_id || '',
  manager_chat_id: settings.manager_chat_id || '',
  // No literal fallback. Empty here means deny-all downstream.
  allowed_chat_ids: (settings.allowed_chat_ids || settings.owner_chat_id || ''),
  sla_hot_hours: num(settings.sla_hot_hours, 4),
  sla_warm_hours: num(settings.sla_warm_hours, 24),
  sla_repeat_hours: num(settings.sla_repeat_hours, 6),
  default_responsible: settings.default_responsible || 'Геннадий',
  ai_model: settings.ai_model || 'gpt-4.1-mini',
  ai_enabled_for_hot: bool(settings.ai_enabled_for_hot, true),
  ai_enabled_for_warm: bool(settings.ai_enabled_for_warm, true),
  ai_enabled_for_cold: bool(settings.ai_enabled_for_cold, false),
  auto_reply_enabled: bool(settings.auto_reply_enabled, false),
  auto_reply_default_lang: (settings.auto_reply_default_lang || 'ru').toLowerCase(),
  follow_up_enabled: bool(settings.follow_up_enabled, false),
  followup_hot_hours: num(settings.followup_hot_hours, 24),
  followup_warm_hours: num(settings.followup_warm_hours, 72),
  timezone: settings.timezone || 'Europe/Chisinau',
  currency: settings.currency || 'EUR'
};
return [{ json: { settings: cfg } }];

// FINMENTOR Command Center v3 — authorisation and command parsing.
//
// Deployed as the n8n Code node "Parse Lead Command v2".
//
// Identity comes ONLY from "Verify Telegram Identity", which derives it from the
// authenticated Telegram Trigger update. No value here originates from a caller-supplied
// HTTP body, and there is no hardcoded owner fallback: the Settings sheet is the single
// authorisation policy source. An absent or empty allowlist denies everyone.
//
// Unauthorised updates return [] — a silent drop. Nothing downstream executes, so there
// are zero Pipeline reads, zero CRM writes and no CRM data in any Telegram reply.

const v = $('Verify Telegram Identity').first().json;
if (!v || v.verified !== true) return [];

const cfg = $('Settings to Object').first().json.settings || {};

// Policy source of truth. Deny-all when unset — never allow-all.
const allowed = String(cfg.allowed_chat_ids ?? '')
  .split(',')
  .map(s => s.trim())
  .filter(Boolean);
if (allowed.length === 0) return [];

const fromId = String(v.verified_from_id);
const chatId = String(v.verified_chat_id);

// Re-assert the private-chat invariant at the authorisation boundary. Defence in depth:
// authorisation and reply destination must be the same identity, checked again here so a
// future change upstream cannot silently reintroduce the from/chat split.
if (!chatId || chatId !== fromId) return [];

// Exact match only. No prefix, substring or numeric coercion.
if (!allowed.includes(fromId)) return [];

const text = String(v.text ?? '').trim();
if (!text) return [];

const isCb = v.is_callback === true;
const cbId = String(v.callback_query_id ?? '');

function base(extra) {
  return Object.assign({
    mode: 'noop', query_type: '', command: '', lead_id: '', args: [],
    snooze_hours: 24, stage_value: '', note_text: '', deal_value: '', close_reason: '', meeting_date: '',
    chat_id: chatId, from_id: fromId, callback_query_id: cbId, is_callback: isCb,
    allowed: true, reply_text: ''
  }, extra || {});
}

// callback_data: "cmd|lead|arg" ; text: "cmd lead arg..."
const parts = isCb
  ? text.split('|').map(s => s.trim())
  : text.replace(/^\//, '/').split(/\s+/);

const cmd = (parts[0] || '').toLowerCase().replace(/^\//, '');
const rest = parts.slice(1);

const HELP =
`FINMENTOR Command Center

Запросы:
/today — новые лиды сегодня
/overdue — просроченные follow-up
/hot — горячие лиды
/pipeline — сводка воронки
/lead <ID> — карточка лида

Действия (<ID> = FIN-/fm-/FM-...):
done <ID> — закрыть SLA
snooze <ID> <часы> — отложить
stage <ID> <стадия> — сменить стадию
meeting <ID> <дата> — назначить встречу
docs <ID> — запросить документы
proposal <ID> — отправлено предложение
nurture <ID> — в подогрев
won <ID> <сумма> — сделка выиграна
lost <ID> <причина> — сделка проиграна
note <ID> <текст> — заметка`;

const queryCmds = { today: 'today', overdue: 'overdue', hot: 'hot', pipeline: 'pipeline' };
const updateCmds = ['done', 'snooze', 'stage', 'meeting', 'docs', 'proposal', 'nurture', 'won', 'lost', 'note'];

if (cmd === 'help' || cmd === 'start') {
  return [base({ mode: 'help', reply_text: HELP })];
}

if (queryCmds[cmd]) {
  return [base({ mode: 'query', query_type: queryCmds[cmd] })];
}

if (cmd === 'lead') {
  const id = rest[0] || '';
  if (!id) return [base({ mode: 'help', reply_text: 'Укажи Lead ID: /lead FIN-...' })];
  return [base({ mode: 'query', query_type: 'lead', lead_id: id })];
}

if (updateCmds.includes(cmd)) {
  const id = rest[0] || '';
  if (!id) return [base({ mode: 'help', reply_text: `Укажи Lead ID: ${cmd} FIN-...` })];
  const o = base({ mode: 'update', command: cmd, lead_id: id, args: rest.slice(1) });
  if (cmd === 'snooze') o.snooze_hours = Number(rest[1]) > 0 ? Number(rest[1]) : 24;
  if (cmd === 'stage') o.stage_value = rest.slice(1).join(' ') || 'Discovery Scheduled';
  if (cmd === 'meeting') o.meeting_date = rest.slice(1).join(' ');
  if (cmd === 'won') o.deal_value = rest[1] || '';
  if (cmd === 'lost') o.close_reason = rest.slice(1).join(' ');
  if (cmd === 'note') o.note_text = rest.slice(1).join(' ');
  return [o];
}

// Unknown command: help text only. No CRM read, no CRM write.
return [base({ mode: 'help', reply_text: 'Неизвестная команда. Напиши /help для списка.' })];

// Формирует ответ на /today /overdue /hot /pipeline /lead
const cmd = $('Parse Lead Command v2').first().json;
const cfg = $('Settings to Object').first().json.settings || {};
const rows = $input.all().map(i => i.json);
const TZ = cfg.timezone || 'Europe/Chisinau';
const now = new Date();

function val(r,...k){ for(const x of k){ if(r[x]!==undefined&&r[x]!==null&&String(r[x]).trim()!=='') return String(r[x]).trim(); } return ''; }
function dkey(v){ const d=new Date(v); return Number.isNaN(d.getTime())?'':d.toLocaleDateString('en-CA',{timeZone:TZ}); }
function today(){ return now.toLocaleDateString('en-CA',{timeZone:TZ}); }
function isClosed(s){ s=s.toLowerCase(); return ['won','lost','closed','nurture','закрыт'].some(x=>s.includes(x)); }
function line(r,i){ return `${i}. ${val(r,'company')||'—'} / ${val(r,'name')||'—'} [${val(r,'priority')||'—'}/${val(r,'financial_zone')||'—'}]\n   ${val(r,'next_action')||'—'} | ${val(r,'lead_id')}`; }

function slaStatus(r) { return val(r,'sla_status').toLowerCase(); }
function isSnoozedFuture(r) {
  const s = slaStatus(r);
  const until = val(r,'sla_snooze_until');
  if (s !== 'snoozed' || !until) return false;
  const d = new Date(until);
  return !Number.isNaN(d.getTime()) && d > now;
}
function isInactiveForOverdue(r) {
  const stage = val(r,'deal_stage').toLowerCase();
  const sla = slaStatus(r);
  return (
    ['won','lost','closed','nurture','incomplete','закрыт'].some(x => stage.includes(x)) ||
    sla === 'done' ||
    sla === 'nurture' ||
    isSnoozedFuture(r)
  );
}

let msg = '';
const t = cmd.query_type;

if (t === 'lead') {
  const r = rows.find(x => val(x,'lead_id').toLowerCase() === String(cmd.lead_id).toLowerCase());
  if (!r) msg = `Lead ID не найден: ${cmd.lead_id}`;
  else msg =
`Карточка лида ${val(r,'lead_id')}
Компания: ${val(r,'company')||'—'}
Контакт: ${val(r,'name')||'—'} | ${[val(r,'phone'),val(r,'telegram'),val(r,'email')].filter(Boolean).join(' · ')||'—'}
Приоритет/Зона: ${val(r,'priority')||'—'} / ${val(r,'financial_zone')||'—'}
Стадия: ${val(r,'deal_stage')||'New'}
Боль: ${val(r,'main_pain')||'—'}
Next action: ${val(r,'next_action')||'—'}
Follow-up: ${val(r,'next_follow_up_at')||'—'}
SLA: ${val(r,'sla_status')||'—'}
AI-план: ${val(r,'ai_plan_ready')||'—'}`;
} else if (t === 'today') {
  const list = rows.filter(r => dkey(val(r,'created_at')) === today());
  msg = `Новые лиды сегодня: ${list.length}\n\n` + (list.length ? list.slice(0,15).map((r,i)=>line(r,i+1)).join('\n') : '—');
} else if (t === 'overdue') {
  const list = rows.filter(r => {
    const f = val(r,'next_follow_up_at');
    if (!f || isInactiveForOverdue(r)) return false;
    const d = new Date(f);
    return !Number.isNaN(d.getTime()) && d < now;
  })
    .sort((a,b)=>new Date(val(a,'next_follow_up_at'))-new Date(val(b,'next_follow_up_at')));
  msg = `Просроченные follow-up: ${list.length}\n\n` + (list.length ? list.slice(0,15).map((r,i)=>line(r,i+1)).join('\n') : '—');
} else if (t === 'hot') {
  const list = rows.filter(r => val(r,'priority').toUpperCase()==='HOT' && !isClosed(val(r,'deal_stage')));
  msg = `HOT лиды: ${list.length}\n\n` + (list.length ? list.slice(0,15).map((r,i)=>line(r,i+1)).join('\n') : '—');
} else if (t === 'pipeline') {
  const active = rows.filter(r => !isClosed(val(r,'deal_stage')));
  const byP = p => active.filter(r => val(r,'priority').toUpperCase()===p).length;
  const stages = {};
  for (const r of active){ const s=val(r,'deal_stage')||'New'; stages[s]=(stages[s]||0)+1; }
  const red = active.filter(r => ['RED','ORANGE'].includes(val(r,'financial_zone').toUpperCase())).length;
  msg = `Воронка (активных: ${active.length})
HOT ${byP('HOT')} · WARM ${byP('WARM')} · COLD ${byP('COLD')} · INCOMPLETE ${byP('INCOMPLETE')}
RED/ORANGE: ${red}

По стадиям:
${Object.entries(stages).map(([k,v])=>`• ${k}: ${v}`).join('\n')||'—'}`;
} else {
  msg = 'Нет данных.';
}

if (msg.length > 3800) msg = msg.slice(0,3800) + '\n...\nПолный список в Google Sheets.';
return [{ json: { reply_text: msg, chat_id: cmd.chat_id, callback_query_id: cmd.callback_query_id } }];

// Находит строку Pipeline по lead_id и строит payload обновления под команду.
const cmd = $('Parse Lead Command v2').first().json;
const rows = $input.all().map(i => i.json);
function norm(v){ return String(v ?? '').trim().toLowerCase(); }
const target = norm(cmd.lead_id);
const row = rows.find(r => norm(r.lead_id) === target);

if (!row) {
  return [{ json: { _found: false, lead_id: cmd.lead_id, chat_id: cmd.chat_id,
    callback_query_id: cmd.callback_query_id,
    reply_text: `Lead ID не найден: ${cmd.lead_id}. Проверь ID или /today.` } }];
}

const now = new Date();
const fromStage = String(row.deal_stage || 'New');
const upd = {
  lead_id: row.lead_id,
  updated_at: now.toISOString(),
  last_activity_at: now.toISOString(),
  deal_stage: row.deal_stage || '',
  next_follow_up_at: row.next_follow_up_at || '',
  last_contacted_at: row.last_contacted_at || '',
  meeting_date: row.meeting_date || '',
  documents_requested_at: row.documents_requested_at || '',
  proposal_sent_at: row.proposal_sent_at || '',
  deal_value_estimate: row.deal_value_estimate || '',
  close_reason: row.close_reason || '',
  sla_status: row.sla_status || '',
  sla_snooze_until: row.sla_snooze_until || '',
  owner_note: row.owner_note || ''
};
let toStage = fromStage;
let confirm = '';

switch (cmd.command) {
  case 'done':
    upd.sla_status = 'Done'; upd.last_contacted_at = now.toISOString();
    confirm = `Готово: SLA закрыт. ${row.company || ''}`.trim(); break;
  case 'snooze': {
    const h = Number(cmd.snooze_hours) || 24;
    const snoozeUntil = new Date(now.getTime() + h * 36e5).toISOString();
    upd.sla_status = 'Snoozed';
    upd.sla_snooze_until = snoozeUntil;
    upd.next_follow_up_at = snoozeUntil;
    confirm = `SLA отложен на ${h} ч.`; break;
  }
  case 'stage':
    toStage = cmd.stage_value || 'Discovery Scheduled'; upd.deal_stage = toStage;
    confirm = `Стадия: ${toStage}`; break;
  case 'meeting':
    toStage = 'Discovery Scheduled'; upd.deal_stage = toStage;
    if (cmd.meeting_date) upd.meeting_date = cmd.meeting_date;
    upd.next_follow_up_at = new Date(now.getTime() + 24 * 36e5).toISOString();
    confirm = `Встреча назначена${cmd.meeting_date ? ': ' + cmd.meeting_date : ''}`; break;
  case 'docs':
    toStage = 'Documents Requested'; upd.deal_stage = toStage;
    upd.documents_requested_at = now.toISOString();
    upd.next_follow_up_at = new Date(now.getTime() + 48 * 36e5).toISOString();
    confirm = 'Документы запрошены (+48ч follow-up)'; break;
  case 'proposal':
    toStage = 'Proposal Sent'; upd.deal_stage = toStage;
    upd.proposal_sent_at = now.toISOString();
    upd.next_follow_up_at = new Date(now.getTime() + 72 * 36e5).toISOString();
    confirm = 'Предложение отправлено'; break;
  case 'nurture':
    toStage = 'Nurture'; upd.deal_stage = toStage; upd.sla_status = 'Nurture';
    confirm = 'Лид переведён в подогрев (SLA выключен)'; break;
  case 'won':
    toStage = 'Won'; upd.deal_stage = toStage; upd.sla_status = 'Done';
    if (cmd.deal_value) upd.deal_value_estimate = cmd.deal_value;
    confirm = `Сделка выиграна${cmd.deal_value ? ': ' + cmd.deal_value : ''}`; break;
  case 'lost':
    toStage = 'Lost'; upd.deal_stage = toStage; upd.sla_status = 'Done';
    if (cmd.close_reason) upd.close_reason = cmd.close_reason;
    confirm = `Сделка проиграна${cmd.close_reason ? ': ' + cmd.close_reason : ''}`; break;
  case 'note':
    upd.owner_note = cmd.note_text || '';
    confirm = 'Заметка сохранена'; break;
  default:
    confirm = 'Обновлено';
}

return [{ json: {
  _found: true,
  ...upd,
  from_stage: fromStage,
  to_stage: toStage,
  stage_changed: toStage !== fromStage,
  command: cmd.command,
  chat_id: cmd.chat_id,
  callback_query_id: cmd.callback_query_id,
  company: row.company || '',
  reply_text: `${confirm}\nLead ID: ${row.lead_id}`
}}];

// Пишет строку Status_Log только при смене стадии.
const item = $('Find & Build Update').first().json;
if (!item.stage_changed) return [];
return [{ json: {
  log_id: `${item.lead_id}-${Date.now()}`,
  ts: new Date().toISOString(),
  lead_id: item.lead_id,
  from_stage: item.from_stage || '',
  to_stage: item.to_stage || '',
  actor: 'telegram:owner',
  reason: `command:${item.command}`
}}];

const item = $('Find & Build Update').first().json;
return [{ json: {
  activity_id: `${item.lead_id}-${Date.now()}`,
  ts: new Date().toISOString(),
  lead_id: item.lead_id,
  actor: 'telegram:owner',
  channel: 'telegram',
  action: `command:${item.command}`,
  detail: item.stage_changed ? `stage ${item.from_stage} -> ${item.to_stage}` : (item.reply_text || '').split('\n')[0]
}}];

// FINMENTOR Command Center — authenticated Telegram identity gate.
//
// Deployed as the n8n Code node "Verify Telegram Identity". Its only upstream is the
// Telegram Trigger, which registers the webhook with Telegram using a secret_token and
// rejects any request whose X-Telegram-Bot-Api-Secret-Token does not match before the
// update ever reaches this workflow. Nothing below trusts a caller-supplied HTTP body.
//
// This node runs BEFORE Settings and before any Pipeline node, so a rejected update
// performs zero Sheets reads, zero CRM writes and produces zero Telegram output.
// Rejection is a silent drop (return []), which also denies an attacker an oracle.

const u = $input.first().json ?? {};

const isCallback = Object.prototype.hasOwnProperty.call(u, 'callback_query');
const cq = isCallback ? u.callback_query : null;
const msg = isCallback ? cq && cq.message : u.message;
const from = isCallback ? cq && cq.from : u.message && u.message.from;

// 1. Sender and chat must both exist and be genuine Telegram numeric ids.
const fromId = from && from.id;
const chatId = msg && msg.chat && msg.chat.id;
if (typeof fromId !== 'number' || !Number.isFinite(fromId)) return [];
if (typeof chatId !== 'number' || !Number.isFinite(chatId)) return [];

// 2. Bots may never drive the Command Center.
if (from.is_bot === true) return [];

// 3. Private chat only. group / supergroup / channel updates are rejected outright.
if (!msg.chat || msg.chat.type !== 'private') return [];

// 4. Owner-private invariant. In a Telegram private chat the chat id always equals the
//    sender id. Enforcing it collapses authorisation identity and reply destination into
//    a single value, which is what removes the from/chat confused-deputy exfiltration:
//    an attacker can no longer authorise as the owner while replying to their own chat.
if (String(chatId) !== String(fromId)) return [];

// 5. Payload must be usable before anything downstream runs.
const text = isCallback ? (cq.data ?? '') : (u.message.text ?? '');
if (typeof text !== 'string' || !text.trim()) return [];

return [{
  json: {
    verified: true,
    verified_from_id: String(fromId),
    verified_chat_id: String(chatId),
    is_callback: isCallback,
    callback_query_id: isCallback ? String(cq.id ?? '') : '',
    text: text.trim(),
    update_id: typeof u.update_id === 'number' ? u.update_id : null
  }
}];
